code_snippets.after:
if free_rate > 0.0:
    give_n = int(round(free_rate * len(self.agents)))
    if give_n > 0:
        id_to_agent = {a.id: a for a in self.agents}
        sample_ids = self.rng.choice([a.id for a in self.agents], size=min(give_n, len(self.agents)), replace=False)
        for pid in sample_ids:
            agent = id_to_agent.get(pid)
            if agent is None:
                continue
            agent.mask_ownership += 1
            hh = self.person_to_household.get(pid, None)
            if hh is not None:
                hh.mask_inventory += 0

# Delayed restock queue
restock_period = int(self.params.get('restock_period_days', 7))
supply_delay = int(self.params.get('supply_delay_days', 2))
if day == 0:
    self._restock_queue = []
# place orders periodically
if restock_period > 0 and (day % restock_period == 0):
    for r in self.retailers:
        self._restock_queue.append({'retailer_id': r.id, 'day_due': day + supply_delay, 'qty': restock_rate_per_day})
# receive due shipments
pending = []
for order in getattr(self, '_restock_queue', []):
    if order['day_due'] <= day:
        rid = order['retailer_id']
        rr = next((x for x in self.retailers if x.id == rid), None)
        if rr is not None:
            rr.stock_level = max(0, rr.stock_level + int(order['qty']))
    else:
        pending.append(order)
self._restock_queue = pending

# Price adjust
for r in self.retailers:
    desired_price = mask_cost * (1.0 + safe_normal(price_markup_mean, price_markup_sd, rng=self.rng))
    scarcity_term = price_adjustment_sensitivity * (1.0 - (r.stock_level / max(1.0, baseline_stock)))
    r.price = max(0.2, desired_price + scarcity_term - subsidy_rate * mask_cost)

